create type diet_type as enum ('veg','egg','nonveg');
create type meal_slot as enum ('breakfast','lunch','dinner');
create type plan_status as enum ('draft','locked');
create table profiles (id uuid primary key references auth.users on delete cascade, full_name text, phone text, created_at timestamptz default now());
create table preferences (user_id uuid primary key references auth.users on delete cascade, goal text check (goal in ('lose','maintain','build')), diet diet_type default 'veg', cuisine text default 'any', spice int check (spice between 1 and 4), oil int check (oil between 1 and 3), meals_per_day int check (meals_per_day in (2,3)), updated_at timestamptz default now());
create table addresses (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users on delete cascade, label text, line1 text not null, line2 text, city text default 'Bengaluru', pincode text, is_default boolean default false);
create table meals (id text primary key, name text not null, slot meal_slot not null, diet diet_type not null, cuisine text not null, kcal int not null, protein_g numeric not null, carbs_g numeric, fat_g numeric, spice int, oil int, price_inr int not null, image_url text, ingredients jsonb default '[]', sourcing_note text);
create table plans (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users on delete cascade, week_start date not null, status plan_status default 'draft', locked_at timestamptz, created_at timestamptz default now(), unique(user_id,week_start));
create table plan_items (id uuid primary key default gen_random_uuid(), plan_id uuid references plans on delete cascade, day int check(day between 0 and 6), slot meal_slot not null, meal_id text references meals, unique(plan_id,day,slot));
create table subscriptions (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users on delete cascade, tier text check(tier in ('flex','weekly','monthly')), status text check(status in ('active','paused','cancelled')), started_at timestamptz default now(), current_period_start date, current_period_end date, price_inr int);
create table orders (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users on delete cascade, plan_id uuid references plans, week_start date not null, status text default 'scheduled', total_inr int not null, payment_status text default 'paid_simulated', payment_reference text unique, delivery_address jsonb, created_at timestamptz default now());
create table order_items (id uuid primary key default gen_random_uuid(), order_id uuid references orders on delete cascade, day int not null, slot meal_slot not null, meal_id text, meal_name text not null, kcal int, protein_g numeric, price_inr int);
alter table profiles enable row level security; alter table preferences enable row level security; alter table addresses enable row level security; alter table meals enable row level security; alter table plans enable row level security; alter table plan_items enable row level security; alter table subscriptions enable row level security; alter table orders enable row level security; alter table order_items enable row level security;
create policy "public catalog" on meals for select using (true);
create policy "own profiles" on profiles for all using (id=auth.uid()) with check (id=auth.uid());
create policy "own preferences" on preferences for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "own addresses" on addresses for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "own plans" on plans for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "own subscriptions" on subscriptions for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "own orders" on orders for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "own plan items" on plan_items for all using (exists(select 1 from plans where plans.id=plan_items.plan_id and plans.user_id=auth.uid()));
create policy "own order items" on order_items for all using (exists(select 1 from orders where orders.id=order_items.order_id and orders.user_id=auth.uid()));